import 'package:atlas_app/intelligence/domain/entities/reader_position.dart';
import 'package:atlas_app/intelligence/domain/entities/story_entity.dart';
import 'package:atlas_app/intelligence/domain/entities/story_event.dart';

/// The structured 5-layer context package generated by the Context Engine.
///
/// Bounded strictly to [position.currentChapter] to guarantee zero spoilers.
class ContextPackage {
  const ContextPackage({
    required this.position,
    required this.immediateWindow,
    required this.entityContext,
    required this.timelineContext,
    this.taskFilter,
    this.estimatedTokens = 0,
  });

  /// Layer 1: Reader position anchor.
  final ReaderPosition position;

  /// Layer 2: Immediate window of recent chapters/excerpts.
  final List<ChapterExcerpt> immediateWindow;

  /// Layer 3: Entities present in the immediate window with current-state facts.
  final List<StoryEntity> entityContext;

  /// Layer 4: Compressed event log involving entities in the immediate window.
  final List<StoryEvent> timelineContext;

  /// Layer 5: Target task identifier used for pruning layers 2-4.
  final String? taskFilter;

  /// Estimated token count of the assembled context.
  final int estimatedTokens;

  ContextPackage copyWith({
    ReaderPosition? position,
    List<ChapterExcerpt>? immediateWindow,
    List<StoryEntity>? entityContext,
    List<StoryEvent>? timelineContext,
    String? taskFilter,
    int? estimatedTokens,
  }) {
    return ContextPackage(
      position: position ?? this.position,
      immediateWindow: immediateWindow ?? this.immediateWindow,
      entityContext: entityContext ?? this.entityContext,
      timelineContext: timelineContext ?? this.timelineContext,
      taskFilter: taskFilter ?? this.taskFilter,
      estimatedTokens: estimatedTokens ?? this.estimatedTokens,
    );
  }
}

